window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c8c95c6953acb101"]={"versions": [{"id": "FIG-c8c95c6953acb101", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Logisches Informationsfluss- und Verarbeitungsdiagramm des AUTOSAR Classic Function Inhibition Manager (FiM) innerhalb der System Services / Basic Software (BSW). Das Diagramm visualisiert die interne Zuordnung und Auswertelogik, über die eingehende Diagnose- und Statusereignisse (Events) mit Function Identifiers (FIDs) verknüpft werden, um deren Freigabestatus („Enable of FID“) zu ermitteln.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Function Inhibition Manager (FIM)</strong>: Übergeordnetes BSW-Modul / logische Verarbeitungseinheit.</li>\n<li><strong>Event-Eingänge (<code>Event_s</code>, <code>Event_t</code>, <code>Event_...</code>)</strong>: Signale bzw. Event-Statusmeldungen (typischerweise vom Diagnostic Event Manager, Dem), die in den FiM eingespeist werden.</li>\n<li><strong>Event-Tabellen / Datenstrukturen (<code>Event_s</code>, <code>Event_t</code>)</strong>: Enthalten Zuordnungslisten bestehend aus:</li>\n<li><code>FID</code>: Liste der betroffenen Function Identifier (z. B. <code>FID_N</code>, <code>FID_L</code> bei <code>Event_s</code> bzw. <code>FID_K</code>, <code>FID_L</code> bei <code>Event_t</code>).</li>\n<li><code>Mask</code>: Konfigurationsmaske zur Filterung der Event-Statusbedingungen (Inhibition-Maske).</li>\n<li><strong>Logische Gatter (<code>≥1</code> mit invertiertem Ausgang / NOR-Funktionalität)</strong>: ODER-Verknüpfung aller auf einen FID wirkenden Inhibit-Bedingungen mit anschließender Negation zur Generierung des Freigabesignals.</li>\n<li><strong>FID-Zustände (<code>FID_K</code>, <code>FID_L</code>, <code>FID_M</code>, <code>FID_N</code>, <code>FID_O</code>, <code>FID_...</code>)</strong>: Interne Repräsentanz der Funktions-Identifikatoren.</li>\n<li><strong>Ausgangsschnittstelle (<code>Enable of FID</code>)</strong>: Bereitstellung des berechneten Freigabestatus an die Software-Components (SWCs) bzw. Funktionsaufrufer.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Externe Ereignisse (<code>Event_s</code>, <code>Event_t</code>, weitere Events) treffen im Function Inhibition Manager ein.</li>\n<li>Für jedes Event wird anhand der zugeordneten Maske geprüft, ob das Event aktiv sperrend wirkt.</li>\n<li>Die Inhibit-Informationen werden auf die verknüpften Ziel-FIDs geleitet (beispielsweise führt <code>Event_s</code> zu Sperrbedingungen für <code>FID_N</code> und <code>FID_L</code>, während <code>Event_t</code> zu Sperrbedingungen für <code>FID_K</code> und <code>FID_L</code> führt).</li>\n<li>Für jeden FID werden alle eingehenden Sperrimpulse über ein <code>≥1</code>-Glied zusammengefasst. Tritt mindestens eine Sperrbedingung auf, schaltet der invertierte Ausgang auf logisch 0 (Inhibition aktiv).</li>\n<li>Das resultierende Signal steuert den Berechtigungszustand des jeweiligen FID und wird über die Freigabe-Schnittstelle (<code>Enable of FID</code>) zur Verfügung gestellt. Liegt kein Sperrereignis vor, ist der Ausgang 1 (Freigabe erteilt).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das konzeptionelle Berechnungsmodell für FiM-Implementierungen gemäß SWS FiM:</p>\n<ul class=\"fig-list\">\n<li>Ein FID kann von mehreren Events gehemmt werden (n:m-Beziehung zwischen Events und FIDs, sichtbar an <code>FID_L</code>, auf den sowohl <code>Event_s</code> als auch <code>Event_t</code> wirken).</li>\n<li>Ein einzelnes Event kann mehrere FIDs hemmen (<code>Event_s</code> sperrt <code>FID_N</code> und <code>FID_L</code>).</li>\n<li>Das Verhalten folgt einer Fail-Safe-Logik: Jeder zutreffende Fehler-/Sperrzustand eines Events führt über die ODER-Invertierung (<code>NOR</code>) zum Entzug der Ausführungsfreigabe (<code>Enable of FID = FALSE</code>).</li>\n<li>Für Implementierer verdeutlicht dies die Trennung zwischen ereignisbasierter Maskierung und FID-bezogener Aggregation.</li>\n</ul>"}, {"id": "FIG-131350bf19dbbfb2", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Logisches Informationsfluss- und Verarbeitungsdiagramm des AUTOSAR Classic Function Inhibition Manager (FiM) innerhalb der System Services / Basic Software (BSW). Das Diagramm visualisiert die interne Zuordnung und Auswertelogik, über die eingehende Diagnose- und Statusereignisse (Events) mit Function Identifiers (FIDs) verknüpft werden, um deren Freigabestatus („Enable of FID“) zu ermitteln.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Function Inhibition Manager (FIM)</strong>: Übergeordnetes BSW-Modul / logische Verarbeitungseinheit.</li>\n<li><strong>Event-Eingänge (<code>Event_s</code>, <code>Event_t</code>, <code>Event_...</code>)</strong>: Signale bzw. Event-Statusmeldungen (typischerweise vom Diagnostic Event Manager, Dem), die in den FiM eingespeist werden.</li>\n<li><strong>Event-Tabellen / Datenstrukturen (<code>Event_s</code>, <code>Event_t</code>)</strong>: Enthalten Zuordnungslisten bestehend aus:</li>\n<li><code>FID</code>: Liste der betroffenen Function Identifier (z. B. <code>FID_N</code>, <code>FID_L</code> bei <code>Event_s</code> bzw. <code>FID_K</code>, <code>FID_L</code> bei <code>Event_t</code>).</li>\n<li><code>Mask</code>: Konfigurationsmaske zur Filterung der Event-Statusbedingungen (Inhibition-Maske).</li>\n<li><strong>Logische Gatter (<code>≥1</code> mit invertiertem Ausgang / NOR-Funktionalität)</strong>: ODER-Verknüpfung aller auf einen FID wirkenden Inhibit-Bedingungen mit anschließender Negation zur Generierung des Freigabesignals.</li>\n<li><strong>FID-Zustände (<code>FID_K</code>, <code>FID_L</code>, <code>FID_M</code>, <code>FID_N</code>, <code>FID_O</code>, <code>FID_...</code>)</strong>: Interne Repräsentanz der Funktions-Identifikatoren.</li>\n<li><strong>Ausgangsschnittstelle (<code>Enable of FID</code>)</strong>: Bereitstellung des berechneten Freigabestatus an die Software-Components (SWCs) bzw. Funktionsaufrufer.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\">\n<li>Externe Ereignisse (<code>Event_s</code>, <code>Event_t</code>, weitere Events) treffen im Function Inhibition Manager ein.</li>\n<li>Für jedes Event wird anhand der zugeordneten Maske geprüft, ob das Event aktiv sperrend wirkt.</li>\n<li>Die Inhibit-Informationen werden auf die verknüpften Ziel-FIDs geleitet (beispielsweise führt <code>Event_s</code> zu Sperrbedingungen für <code>FID_N</code> und <code>FID_L</code>, während <code>Event_t</code> zu Sperrbedingungen für <code>FID_K</code> und <code>FID_L</code> führt).</li>\n<li>Für jeden FID werden alle eingehenden Sperrimpulse über ein <code>≥1</code>-Glied zusammengefasst. Tritt mindestens eine Sperrbedingung auf, schaltet der invertierte Ausgang auf logisch 0 (Inhibition aktiv).</li>\n<li>Das resultierende Signal steuert den Berechtigungszustand des jeweiligen FID und wird über die Freigabe-Schnittstelle (<code>Enable of FID</code>) zur Verfügung gestellt. Liegt kein Sperrereignis vor, ist der Ausgang 1 (Freigabe erteilt).</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Das Diagramm definiert das konzeptionelle Berechnungsmodell für FiM-Implementierungen gemäß SWS FiM:</p>\n<ul class=\"fig-list\">\n<li>Ein FID kann von mehreren Events gehemmt werden (n:m-Beziehung zwischen Events und FIDs, sichtbar an <code>FID_L</code>, auf den sowohl <code>Event_s</code> als auch <code>Event_t</code> wirken).</li>\n<li>Ein einzelnes Event kann mehrere FIDs hemmen (<code>Event_s</code> sperrt <code>FID_N</code> und <code>FID_L</code>).</li>\n<li>Das Verhalten folgt einer Fail-Safe-Logik: Jeder zutreffende Fehler-/Sperrzustand eines Events führt über die ODER-Invertierung (<code>NOR</code>) zum Entzug der Ausführungsfreigabe (<code>Enable of FID = FALSE</code>).</li>\n<li>Für Implementierer verdeutlicht dies die Trennung zwischen ereignisbasierter Maskierung und FID-bezogener Aggregation.</li>\n</ul>"}], "trans": [{"from": "FIG-c8c95c6953acb101", "to": "FIG-131350bf19dbbfb2", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
